function build(api) {
  api.name('风草铃花精灵');

  const C_LIGHT_GREEN = 0x90EE90;
  const C_GREEN = 0x3CB371;
  const C_DARK_GREEN = 0x2E8B57;
  const C_PALE_BLUE = 0xADD8E6;
  const C_DEEP_BLUE = 0x6495ED;
  const C_GOLD = 0xFFD700;
  const C_ORANGE = 0xFFA500;

  // Head
  api.group('head', '头部');
  api.cone({ r: 0.9, h: 1.4, along: '-Y', pos: [0, 6.2, 0], color: C_PALE_BLUE });
  api.cyl({ r: 0.15, h: 0.3, pos: [0, 6.9, 0], color: C_GREEN });
  api.poly({ r: 0.12, pos: [0, 7.1, 0], color: C_GOLD });
  api.radial({ count: 5, from: [0, 5.5, 0], axis: 'y', shape: { type: 'tri', a: [0.1, 0, 0], b: [0.5, -0.4, 0.15], c: [0.1, -0.4, 0.2], d: 0.06 }, color: C_DEEP_BLUE });
  api.chain({ waypoints: [[0, 7.1, 0], [0.2, 7.8, 0.1], [-0.1, 8.3, -0.1], [0.15, 8.7, 0.05]], r: 0.05, color: C_LIGHT_GREEN });
  api.chain({ waypoints: [[0, 7.1, 0], [-0.2, 7.7, -0.1], [0.1, 8.2, 0.1], [-0.15, 8.6, -0.05]], r: 0.05, color: C_LIGHT_GREEN });
  api.poly({ r: 0.2, pos: [0.35, 6.0, 0.7], color: 0x1a1a1a });
  api.poly({ r: 0.2, pos: [-0.35, 6.0, 0.7], color: 0x1a1a1a });
  api.poly({ r: 0.1, pos: [0.35, 6.05, 0.82], color: 0xffffff });
  api.poly({ r: 0.1, pos: [-0.35, 6.05, 0.82], color: 0xffffff });
  api.endGroup();

  // Body
  api.group('body', '躯干');
  api.group('chest', '胸');
  api.cyl({ r: 0.45, h: 1.2, pos: [0, 4.8, 0], color: C_LIGHT_GREEN });
  api.box({ w: 0.6, h: 0.08, d: 0.9, pos: [0, 4.8, 0.25], color: C_GREEN });
  api.endGroup();
  api.group('abdomen', '腹');
  api.cyl({ r: 0.35, h: 1.0, pos: [0, 3.7, 0], color: C_LIGHT_GREEN });
  api.torus({ r: 0.35, tube: 0.06, pos: [0, 3.7, 0], color: C_DARK_GREEN });
  api.endGroup();
  api.group('pelvis', '胯');
  api.cyl({ r: 0.4, h: 0.8, pos: [0, 2.8, 0], color: C_LIGHT_GREEN });
  api.endGroup();
  api.endGroup();

  // Arms
  api.mirror('x');
  api.group('leftArm', '左臂');
  api.chain({
    waypoints: [[-0.5, 4.8, 0], [-0.8, 3.8, 0.2], [-0.6, 2.8, 0.4]],
    jointIds: ['upperArm', 'forearm', 'hand'],
    r: 0.15,
    color: C_LIGHT_GREEN
  });
  api.tri({ a: [-0.6, 2.8, 0.4], b: [-1.2, 2.2, 0.8], c: [-0.6, 2.2, 1.0], d: 0.06, color: C_GREEN });
  api.tri({ a: [-0.6, 2.8, 0.4], b: [-0.2, 2.2, 0.8], c: [-0.6, 2.2, 1.0], d: 0.06, color: C_DARK_GREEN });
  api.endGroup();
  api.endMirror();

  // Legs
  api.mirror('x');
  api.group('leftLeg', '左腿');
  api.chain({
    waypoints: [[-0.3, 2.4, 0], [-0.4, 1.2, 0.1], [-0.3, 0.2, 0.2]],
    jointIds: ['thigh', 'shin', 'foot'],
    r: 0.15,
    color: C_LIGHT_GREEN
  });
  api.fork({ from: [-0.3, 0.2, 0.2], to: [[-0.6, 0, 0.4], [-0.1, 0, 0.5], [-0.4, 0, 0.8]], r: 0.04, color: C_DARK_GREEN });
  api.endGroup();
  api.endMirror();

  // Tail
  api.group('tail', '尾巴');
  api.chain({
    waypoints: [[0, 2.4, -0.4], [0.3, 1.8, -1.0], [0.1, 1.2, -1.5], [0.4, 0.8, -1.8]],
    r: 0.1,
    color: C_LIGHT_GREEN
  });
  api.sphere({ r: 0.25, pos: [0.4, 0.8, -1.8], color: C_PALE_BLUE });
  api.cyl({ r: 0.06, h: 0.2, pos: [0.4, 0.55, -1.8], color: C_GOLD });
  api.endGroup();
}
